# ---------------------------------------------------------------- S54
S(54, 'Speculation, crypto assets, and investment fraud', 'Recognize speculation and common investment frauds and protect yourself',
  main=[
    q('A message promises "a guaranteed 20% return every month with no risk." What is the best response?', 'Treat it as a likely scam and do not invest',
      [('Invest a small amount to test it before investing more', 'Scams often pay small early returns to build trust'), ('Invest quickly before the offer ends tonight', 'Responds to pressure'), ('Ask the sender for a written guarantee first', 'A guarantee from a scammer means nothing')],
      intro='Red flags of investment fraud include guaranteed high returns with little or no risk, pressure to act quickly, unregistered sellers, and complicated or secret strategies. Legitimate investments carry risk, and no one can guarantee high returns.',
      fb='Guaranteed high returns with no risk is the classic sign of fraud.', sub='Red flags'),
    q('In a Ponzi scheme, where does the money paid to early investors come from?', 'From newer investors\' money',
      [('From real profits on the investments', 'Believes the story'), ('From government insurance', 'Believes schemes are insured'), ('From interest earned at a bank', 'Believes the returns are real interest')],
      intro='A Ponzi scheme pays existing investors with money from new investors instead of real profits. It collapses when new money slows, and most investors lose money.',
      fb='Ponzi schemes recycle new investors\' money to pay earlier investors.', sub='Ponzi schemes'),
    q('A crypto token rises 300% in a month after heavy social media promotion. Which statement is MOST accurate?', 'It is highly speculative and could fall just as fast',
      [('It is guaranteed to keep rising', 'Assumes momentum'), ('It is protected by FDIC insurance up to $250,000 per owner', 'Confuses crypto with deposits'), ('It is a safe place for an emergency fund', 'Ignores volatility')],
      intro='Speculation is buying something mainly hoping its price rises quickly, often without regard to its underlying value. Crypto assets are highly volatile, are not FDIC insured, and have been targets of fraud and "pump-and-dump" schemes.',
      fb='Rapid hype-driven gains are speculative and can reverse quickly.', sub='Speculation and crypto'),
    q('Before investing through someone, which free tool checks whether they are registered?', 'FINRA BrokerCheck or the SEC\'s Investment Adviser search',
      [('The person\'s social media follower count', 'Popularity is not registration'), ('A testimonial video posted online by a satisfied investor', 'Can be fake'), ('The professional look of their website', 'Easy to fake')],
      intro='Most people who sell securities or give investment advice must be registered. Investors can check registration and disciplinary history for free.',
      fb='Registration checks are free and quick.', sub='Checking registration', how=True),
    q('Pumpers buy a little-known stock, hype it online, and sell when others rush in. What is this called?', 'A pump-and-dump scheme',
      [('Dollar-cost averaging scheme', 'Legitimate strategy'), ('Diversification', 'Legitimate strategy'), ('Rebalancing', 'Legitimate strategy')],
      intro='In a pump-and-dump, promoters spread false or misleading hype to push up a price, then sell their shares at the high price, leaving others with losses.',
      fb='Promoters "pump" the price, then "dump" their shares.', sub='Pump and dump'),
  ],
  back=[
    concept('If it sounds too good to be true', 'Fraud resistance rests on comparing a claim with realistic returns and risks.', [
      q('Insured savings pay about 4% a year, and stocks have historically averaged under 10% a year with large swings. A "no-risk 10% per month" offer is…', 'far beyond any realistic, risk-free return',
        [('reasonable for a new, fast-growing company', 'Misjudges'), ('the same as a savings account', 'Misjudges'), ('normal for index funds', 'Misjudges')],
        intro='Knowing typical returns helps spot offers that are too good to be true. No legitimate investment offers high returns with no risk.',
        fb='10% per month (over 200% a year) with no risk is unrealistic.', sub='Realistic returns'),
      q('A stranger online offers to "double your money in a week." What should you assume?', 'It is very likely a scam',
        [('It is a normal investment', 'Misjudges'), ('It is insured', 'Believes high returns can be insured'), ('It is approved by the government', 'Believes an offer\'s claims of approval')],
        fb='Promises of quick, huge gains are scam hallmarks.', sub='Too good to be true'),
      q('Which is a common pressure tactic?', '"Act now — this opportunity closes tonight!"',
        [('"Take your time and compare all your options first."', 'Not pressure'), ('"Read the prospectus first."', 'Not pressure'), ('"Talk to someone you trust."', 'Not pressure')],
        intro='Scammers create urgency so victims do not stop to check.',
        fb='Urgency discourages careful checking.', sub='Pressure'),
      q('Which payment method do investment scammers often ask for because it is hard to reverse?', 'Crypto transfers, wires, or gift cards',
        [('A credit card with dispute rights', 'Easier to dispute'), ('A check to a registered broker-dealer', 'Traceable'), ('An ACH transfer to your own brokerage account', 'Your own account')],
        intro='Payments that are fast and hard to reverse are favored by scammers.',
        fb='Irreversible payment methods are a scam warning sign.', sub='Payment red flags'),
      q('A friend earned money in a "club" that pays you for recruiting new members, not for selling products. What is this most likely?', 'A pyramid scheme',
        [('A multilevel marketing company that sells real products', 'Confuses recruitment pay with product sales'), ('An investment club that pools money', 'Confuses pooling with recruiting'), ('A referral bonus program', 'Misses that recruiting is the only source of pay')],
        intro='Pyramid schemes pay mainly for recruiting others, not for real products or profits, and collapse when recruiting slows.',
        fb='Paying for recruitment rather than real sales is a pyramid scheme sign.', sub='Pyramid schemes'),
    ]),
    math('Find a percent increase or a percent decrease', 'Judging claimed returns requires comparing percent gains.', 'grade_7', 8),
  ],
  go=[
    deeper('Crypto assets: risks and protections', [
      q('Kai buys $500 of a crypto asset that falls 80%. What is it worth?', '$100',
        [('$400', 'Gives the loss'), ('$420', 'Subtracts 80 dollars'), ('$500', 'Ignores the loss')],
        intro='Crypto assets can lose most of their value quickly. Only money you can afford to lose should be used for speculation.',
        fb='$500 × 0.20 = $100.', calc=100, sub='Volatility'),
      q('Kai\'s crypto exchange collapses, and customers cannot withdraw. Which protection generally applies to the crypto assets?', 'Usually none like FDIC or SIPC coverage',
        [('FDIC insurance up to $250,000 per depositor', 'Crypto is not a deposit'), ('SIPC insurance on all crypto holdings', 'Generally not covered'), ('Automatic refunds from the federal government', 'Assumes a government backstop')],
        intro='Crypto assets are not bank deposits and are generally not protected the way deposits or securities at SIPC-member firms are.',
        fb='Crypto holdings are generally not FDIC insured or SIPC protected.', sub='Lack of protections'),
      q('Who controls access to crypto held in a "self-custody" wallet?', 'Whoever has the private keys or recovery phrase',
        [('The FDIC', 'Believes crypto wallets are insured'), ('The crypto exchange that sold the coins', 'Confuses self-custody with an exchange account'), ('The wallet app\'s customer service team', 'Believes support can recover keys')],
        intro='Crypto wallets are controlled by private keys or recovery phrases. Anyone who gets them can take the assets, and lost keys can mean lost assets.',
        fb='Keys control the wallet; never share a recovery phrase.', sub='Private keys'),
      q('Someone asks Kai for his crypto wallet recovery phrase to "verify his account." What should he do?', 'Refuse; sharing it gives away control of the assets',
        [('Share it, since verification requests like this are routine', 'Gives away control'), ('Share only half of it', 'Still unsafe'), ('Post it publicly to prove ownership', 'Unsafe')],
        intro='Legitimate services never need your recovery phrase.',
        fb='No legitimate service asks for a recovery phrase.', sub='Phrase scams', how=True),
      q('What share of savings is reasonable for highly speculative assets?', 'Only money you could afford to lose entirely',
        [('All emergency savings', 'Too risky'), ('Money borrowed on a credit card', 'Adds debt risk'), ('Money that is needed for next month\'s rent payment', 'Too risky')],
        fb='Speculation should use only money you can afford to lose.', sub='Position size'),
    ]),
    deeper('Protecting yourself and reporting fraud', [
      q('Where can an investor report suspected securities fraud?', 'The SEC (sec.gov/tcr) or the state securities regulator',
        [('Only to the person running the scheme', 'Unhelpful'), ('A credit bureau', 'Wrong agency'), ('The FDIC', 'Wrong agency')],
        intro='The SEC accepts tips and complaints online; state securities regulators also investigate investment fraud.',
        fb='The SEC and state regulators investigate investment fraud.', sub='Reporting', how=True),
      q('A scam targets members of a club or faith group by using trust within the group. What is this called?', 'Affinity fraud',
        [('A pyramid scheme', 'Related, but defined by recruiting, not group trust'), ('Pump-and-dump', 'Related, but defined by price hype'), ('Phishing', 'Related, but uses fake messages')],
        intro='Ponzi schemes pay early investors with new investors\' money. Pump-and-dump schemes hype a cheap stock, then sell. Phishing uses fake messages to steal information. Affinity fraud spreads through trust within a religious, ethnic, or community group.',
        fb='Affinity fraud uses group trust to spread a scam.', sub='Affinity fraud'),
      q('After losing money to a scam, Lia gets a call offering to "recover your losses for a fee." What is this most likely?', 'A recovery scam targeting past victims',
        [('A government refund program', 'Usually untrue'), ('A bank\'s fraud department follow-up', 'Real banks do not charge to recover funds'), ('A legitimate free service in every case', 'Overstates')],
        intro='Recovery scammers target people who already lost money, promising to get it back for an upfront fee.',
        fb='Up-front fees to "recover" losses are a common follow-up scam.', sub='Recovery scams'),
      q('Which habit gives the best protection against investment fraud?', 'Verify registration and take time to research before investing',
        [('Trusting anyone with a professional website', 'Websites are easy to fake'), ('Investing quickly when friends do', 'Social pressure'), ('Choosing the highest promised return', 'Red flag')],
        fb='Checking registration and slowing down defeat most scams.', sub='Prevention', how=True),
      q('A celebrity endorses a new token on social media. What should an investor remember?', 'Endorsements may be paid and are not evidence of value',
        [('Celebrities must guarantee results', 'Invents a rule'), ('Endorsed tokens are FDIC insured', 'Confuses crypto with deposits'), ('Endorsements prove the SEC approved it', 'Confuses fame with regulation')],
        intro='Paid promotions must be disclosed, but endorsements do not make an investment safe or valuable.',
        fb='Promotion is not proof of value; research independently.', sub='Endorsements'),
    ]),
  ],
  nat=('Investing', 'Evaluate investment risks, speculation, and fraud, and identify investor protections'), nj=['FI', 'FP'],
  status='time_sensitive', sources=[FRAUD, CRYPTO], extra=['Checking registration before investing', 'Reporting investment fraud'])
